from functools import wraps
from taf.gnb.oam.coam.cu.exception import M2MInterfaceDisabled


def m2m_interface_availability_check(func):
    """
    Decorator that reports to User that M2M Interface is disabled and what steps should be taken
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            result = func(*args, **kwargs)
        except Exception as exp:
            if "Machine-to-Machine interface was disabled" in str(exp):
                msg = "Machine-to-Machine interface was disabled. Please set parameter actCli on BTS to True and " \
                      "try again."
                raise M2MInterfaceDisabled(msg)
            else:
                raise
        return result
    return wrapper
